// Kill a queued correction inside its window.
//
// The whole endpoint is one conditional UPDATE (see undoCorrection). It is the
// mirror of the dispatcher's claim, so the two race cleanly and the loser is
// told which way it went — "already posted" and "already killed" are different
// facts to somebody watching a countdown run out.

import { NextResponse, type NextRequest } from "next/server";
import { requireTier } from "@/app/_lib/billing/guard";
import { undoCorrection } from "@/app/_lib/corrections/schedule";

export const runtime = "nodejs";

export async function POST(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  // ⛔ PRO. The kill window is part of the corrections feature it belongs to.
  const gate = await requireTier("pro");
  if ("deny" in gate) return gate.deny;
  const user = gate.user;

  const result = await undoCorrection({
    userId: user.id,
    actor: user.email ?? user.id,
    correctionId: id,
  });
  return NextResponse.json(result, { status: result.ok ? 200 : 409 });
}

